15	/**
16	 * 导入 CSV 文件。整批成功或整批拒绝:
17	 * 任一行格式错误或读数冲突都不写入任何新数据。
18	 * 返回进程退出码。
19	 */
20	export function cmdImport(file: string): number {
21	  const storePath = dataFilePath();
22	
23	  let data: StoreData;
24	  try {
25	    data = loadData(storePath);
26	  } catch (e) {
27	    if (e instanceof StoreError) {
28	      err(e.message);
29	      return 1;
30	    }
31	    throw e;
32	  }
33	  const existing = data.readings;
34	
35	  let text: string;
36	  try {
37	    text = readFileSync(file, 'utf8');
38	  } catch (e) {
39	    err(`cannot read '${file}': ${(e as Error).message}`);
40	    return 1;
41	  }
42	
43	  let records;
44	  try {
45	    records = parseCsv(text);
46	  } catch (e) {
47	    if (e instanceof CsvError) {
48	      err(`${file}: ${e.message}`);
49	      return 1;
50	    }
51	    throw e;
52	  }
53	
54	  if (records.length === 0) {
55	    err(`${file}: empty file, expected header '${CSV_HEADER}'`);
56	    return 1;
57	  }
58	  const header = records[0];
59	  if (header.fields.length !== 3 || header.fields.join(',') !== CSV_HEADER) {
60	    err(`${file}: line ${header.line}: expected header '${CSV_HEADER}'`);
61	    return 1;
62	  }
63	
64	  // 逐行解析,收集全部格式错误。
65	  const errors: string[] = [];
66	  const rows: Array<Reading & { line: number }> = [];
