/**
 * preparing 阶段的前滚:换名尚未开始(阶段翻到 committing 前不会换名),
 * 故每个业务存储都应是原位旧文件 + 待换入新临时并存、无旧备份。逐文件先把
 * 原位旧文件移为备份(原本缺失则跳过),再把新临时换入。任何偏离预期的
 * 状态都抛错(材料保留),由调用方改走回滚。
 */
function rollForwardFromPreparing(dir: string, journal: Journal): void {
  for (const f of journal.files) {
    const target = join(dir, f.name);
    const newPath = target + NEW_SUFFIX;
    const oldPath = target + OLD_SUFFIX;
    if (existsSync(oldPath)) {
      throw new StoreError(`unexpected restore backup ${oldPath} in preparing phase`);
    }
    if (!isRegularFile(newPath)) {
      throw new StoreError(`restore temp file ${newPath} is missing or not a regular file`);
    }
