#!/usr/bin/env node
// 按规格在数据目录中构造一次恢复事务"被杀死后"的磁盘状态。
// 用法: node mkstate.mjs <dataDir> <phase> <spec>
//   phase: preparing | committing | rolling-back | done
//   spec : readings,alerts,groups 三项,每项 "hadOld:slot",例如 "1:moved,0:new,1:old-new"
//   slot 描述该业务存储此刻在磁盘上的布局:
//     old-new : 原位=旧(hadOld 时,否则缺失)+新临时在+无旧备份   (换名未开始 / 回滚未开始)
//     moved   : 原位缺失+新临时在+旧备份在                         (旧已移走,新未换入)
//     new     : 原位=新+无新临时+(hadOld?旧备份在:无)             (已换入)
//     old     : 原位=旧+无新临时+无旧备份                          (回滚已还原)
import { writeFileSync, mkdirSync, rmSync, existsSync } from 'node:fs';
import { join } from 'node:path';

const [, , dir, phase, spec] = process.argv;
const names = ['readings.json', 'alerts.json', 'groups.json'];
const bodies = {
  'readings.json': [process.env.OLD_READINGS, process.env.NEW_READINGS],
  'alerts.json': [process.env.OLD_ALERTS, process.env.NEW_ALERTS],
  'groups.json': [process.env.OLD_GROUPS, process.env.NEW_GROUPS],
};

mkdirSync(dir, { recursive: true });
// 清掉业务文件、临时文件、备份与日志,再按规格重建(保留 other.txt)。
for (const n of names) {
  for (const p of [n, n + '.restore-new', n + '.restore-old']) {
    const q = join(dir, p);
    if (existsSync(q)) rmSync(q, { recursive: true, force: true });
  }
}
const journalPath = join(dir, 'restore.journal');
if (existsSync(journalPath)) rmSync(journalPath);

const files = [];
spec.split(',').forEach((item, i) => {
  const [hadRaw, slot] = item.split(':');
  const hadOld = hadRaw === '1';
  const name = names[i];
  const [oldBody, newBody] = bodies[name];
  const target = join(dir, name);
  const newP = target + '.restore-new';
  const oldP = target + '.restore-old';
  const put = (p, body, forceDir = false) => {
    if (forceDir) {
      mkdirSync(p, { recursive: true });
    } else {
      writeFileSync(p, body, 'utf8');
    }
  };
  switch (slot) {
    case 'old-new':
      if (hadOld) put(target, oldBody);
      put(newP, newBody);
      break;
    case 'moved':
      put(oldP, oldBody);
      put(newP, newBody);
      break;
    case 'new':
      put(target, newBody);
      if (hadOld) put(oldP, oldBody);
      break;
    case 'old':
      put(target, oldBody);
      break;
    case 'newdir': // 新临时是目录(用于制造前滚/回滚受阻)
      if (hadOld) put(target, oldBody);
      put(newP, null, true);
      break;
    case 'targetdir': // 原位是目录(制造异常)
      put(target, null, true);
      put(newP, newBody);
      break;
    default:
      throw new Error(`unknown slot ${slot}`);
  }
  files.push({ name, hadOld });
});

writeFileSync(
  journalPath,
  JSON.stringify({ format: 'meterwatch-restore-journal', version: 1, phase, files }, null, 2) + '\n',
  'utf8',
);

