308	// ---------------------------------------------------------------------------
309	// 回滚(还原完整旧库)——幂等,可跨中断续接
310	// ---------------------------------------------------------------------------
311	
312	/**
313	 * 回滚到恢复前状态。必须在 journal.phase === 'rolling-back' 下调用。
314	 *
315	 * 幂等且可在任意一步中断后续接:
316	 * - 旧文件备份存在:原位若为常规文件则删除,再把备份原子换回(rename 覆盖
317	 *   已先删除,故不会因 EEXIST 失败);已还原到原位的旧文件不会被误删。
318	 * - 原本缺失(hadOld=false):旧备份按定义不存在;删除事务换入的新内容,
319	 *   恢复为缺失。原位不存在时即为已完成,绝不把缺文件当成空库而补写。
320	 * - hadOld=true 但原位与旧备份同时缺失:状态被外部破坏,无法可靠还原,
321	 *   抛错并保留全部材料,不猜测。
322	 * 旧备份与待换入新内容必须是常规文件,否则按被篡改处理,中止回滚。
323	 */
324	function rollbackPass(dir: string, journal: Journal): void {
325	  for (const f of journal.files) {
326	    const target = join(dir, f.name);
327	    const oldPath = target + OLD_SUFFIX;
328	    const newPath = target + NEW_SUFFIX;
329	    if (isRegularFile(oldPath)) {
330	      if (existsSync(target)) {
331	        if (!isRegularFile(target)) {
332	          throw new StoreError(`cannot roll back ${target}: target exists but is not a regular file`);
333	        }
334	        rmSync(target);
335	      }
336	      renameSync(oldPath, target);
337	    } else if (existsSync(oldPath)) {
338	      throw new StoreError(`restore backup ${oldPath} is not a regular file`);
339	    } else if (f.hadOld) {
340	      if (!existsSync(target)) {
341	        throw new StoreError(`cannot roll back ${target}: both the original and its backup are missing`);
342	      }
343	      if (!isRegularFile(target)) {
344	        throw new StoreError(`cannot roll back ${target}: restored original is not a regular file`);
345	      }
346	      // 原位已是常规文件:上一轮已还原完成,保持不动(绝不误删)。
347	    } else {
348	      // 原本缺失:清除事务换入的内容(原位或残留新临时文件),恢复为缺失。
349	      if (existsSync(newPath)) {
350	        if (!isRegularFile(newPath)) {
351	          throw new StoreError(`restore temp file ${newPath} is not a regular file`);
352	        }
353	        rmSync(newPath);
354	      }
355	      if (existsSync(target)) {
356	        if (!isRegularFile(target)) {
357	          throw new StoreError(`cannot restore missing state for ${target}: target is not a regular file`);
358	        }
359	        rmSync(target);
360	      }
361	    }
362	  }
363	}
364	
365	/** 回滚收尾:删除残留新临时文件,再删日志。旧文件备份已全部换回原位。 */
366	function rollbackCleanup(dir: string, journal: Journal): void {
367	  for (const f of journal.files) {
368	    const newPath = join(dir, f.name) + NEW_SUFFIX;
369	    if (existsSync(newPath)) {
370	      // 该名字属于本次事务的临时命名空间;正常产物必为常规文件。即便是异常
371	      // 占位(如目录),也随回滚一并递归清除,不影响业务存储。
372	      rmSync(newPath, { recursive: true, force: true });
373	    }
374	    const oldPath = join(dir, f.name) + OLD_SUFFIX;
375	    if (existsSync(oldPath)) {
376	      // 正常不应残留;若仍在则回滚未完成,保留材料并报错,不删日志。
377	      throw new StoreError(`restore backup ${oldPath} was not restored; rollback is incomplete`);
378	    }
379	  }
380	  rmSync(join(dir, JOURNAL_NAME));
381	}
382	
383	// ---------------------------------------------------------------------------
384	// 前滚(提交完整快照)——幂等,可跨中断续接
385	// ---------------------------------------------------------------------------
386	
387	/**
388	 * 前滚到完整快照状态,逐文件幂等,可在任意一步中断后续接。每个文件只有崩溃
389	 * 可达的三种状态:
